package com.axplatform.sheet;
import java.util.*;
/** Small explicit OOXML style registry shared by all workbook sheets. */
final class XlsxStyles {
 private final List<Map<String,Object>> entries=new ArrayList<>();private final Map<Map<String,Object>,Integer> ids=new HashMap<>();
 private static String esc(Object v){return Objects.toString(v,"").replace("&","&amp;").replace("\"","&quot;").replace("<","&lt;");}
 @SuppressWarnings("unchecked") int cell(Map<String,Object> sheet,int row,int col){
  var column=((List<Map<String,Object>>)sheet.get("columns")).get(col);var style=new LinkedHashMap<String,Object>();
  if(sheet.get("presentation") instanceof Map<?,?> p&&p.get("cellStyles") instanceof List<?> rows&&row<rows.size()&&rows.get(row) instanceof List<?> cs&&col<cs.size()&&p.get("styles") instanceof List<?> ss){int id=((Number)cs.get(col)).intValue();style.putAll((Map<String,Object>)ss.get(id));}
  else if(row==0){style.put("bold",true);style.put("background","#145E65");style.put("color","#FFFFFF");}
  String fmt="General";if(row>0){String zeros=((Number)column.getOrDefault("decimals",0)).intValue()>0?"."+"0".repeat(((Number)column.getOrDefault("decimals",0)).intValue()):"";fmt=switch(Objects.toString(column.get("format"),"PLAIN")){case "NUMBER"->"#,##0"+zeros;case "CURRENCY"->"₩#,##0"+zeros;case "PERCENT"->"0"+zeros+"%";default->"DATE".equals(column.get("type"))?"yyyy-mm-dd":"General";};}var original=ExcelCells.<List<String>>map(ExcelCells.meta(sheet),"values").get(ExcelCells.ref(row,col));if(original!=null&&!original.get(3).isEmpty()&&(!column.containsKey("format")||"PLAIN".equals(column.get("format"))))fmt=original.get(3);style.put("format",fmt);
  return ids.computeIfAbsent(Map.copyOf(style),k->{if(entries.size()>20000)throw com.axplatform.common.Problem.invalid("내보낼 셀 서식이 너무 많습니다.");entries.add(k);return entries.size()-1;});
 }
 String xml(){if(entries.isEmpty()){entries.add(Map.of("format","General"));}var b=new StringBuilder("<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><numFmts count=\""+entries.size()+"\">");for(int i=0;i<entries.size();i++)b.append("<numFmt numFmtId=\"").append(164+i).append("\" formatCode=\"").append(esc(entries.get(i).get("format"))).append("\"/>");b.append("</numFmts><fonts count=\"").append(entries.size()).append("\">");for(var s:entries){b.append("<font><sz val=\"11\"/><name val=\"맑은 고딕\"/>");if(Boolean.TRUE.equals(s.get("bold")))b.append("<b/>");if(s.containsKey("color"))b.append("<color rgb=\"FF").append(s.get("color").toString().substring(1)).append("\"/>");b.append("</font>");}b.append("</fonts><fills count=\"").append(entries.size()+2).append("\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill>");for(var s:entries){b.append("<fill><patternFill patternType=\"").append(s.containsKey("background")?"solid":"none").append("\">");if(s.containsKey("background"))b.append("<fgColor rgb=\"FF").append(s.get("background").toString().substring(1)).append("\"/><bgColor indexed=\"64\"/>");b.append("</patternFill></fill>");}b.append("</fills><borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"").append(entries.size()).append("\">");for(int i=0;i<entries.size();i++)b.append("<xf numFmtId=\"").append(164+i).append("\" fontId=\"").append(i).append("\" fillId=\"").append(i+2).append("\" borderId=\"0\" xfId=\"0\" applyFont=\"1\" applyFill=\"1\" applyNumberFormat=\"1\" applyAlignment=\"1\"><alignment vertical=\"top\" horizontal=\"").append(entries.get(i).getOrDefault("align","general")).append("\" wrapText=\"1\"/></xf>");return b.append("</cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>").toString();}
}
